mapper.select:
select ua.id as id,ua.member_id as memberId,ua.company_id as companyId,ua.member_role as memberRole,ua.post_name as postName ,ua.create_time as createTime, su.realname as realname,su.avatar as avatar,su.phone as phone from ums_member_role ua left join sys_user su on su.id = ua.member_id where 1 = 1
AND ua.company_id = #{paramCondition.companyId}
order by ua.member_role desc
